-- booking-service schema. Money is numeric(12,2) plus an ISO currency, time is timestamptz (UTC),
-- ids are generated by the application. Every index below names the query that needs it.

-- ---------------------------------------------------------------------------------------------
-- Projection of the catalog: what bookings need to know about an event, fed by catalog events.
-- starts_at / ends_at are NULL only for a tombstone (a cancellation that arrived before the
-- publication); such a row has no zones either.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE event_projection (
    event_id         uuid        PRIMARY KEY,
    status           varchar(16) NOT NULL,
    starts_at        timestamptz,
    ends_at          timestamptz,
    last_occurred_at timestamptz NOT NULL,
    version          bigint      NOT NULL DEFAULT 0,
    CONSTRAINT ck_event_projection_status CHECK (status IN ('OPEN', 'CANCELLED')),
    CONSTRAINT ck_event_projection_schedule CHECK ((starts_at IS NULL) = (ends_at IS NULL)),
    CONSTRAINT ck_event_projection_open_is_scheduled CHECK (status = 'CANCELLED' OR starts_at IS NOT NULL)
);

CREATE TABLE projected_zone (
    event_id       uuid        NOT NULL REFERENCES event_projection (event_id) ON DELETE CASCADE,
    zone_id        uuid        NOT NULL,
    position       integer    NOT NULL,
    name           text        NOT NULL,
    price_amount   numeric(12, 2) NOT NULL,
    price_currency varchar(3)  NOT NULL,
    capacity       integer     NOT NULL,
    PRIMARY KEY (event_id, zone_id),
    CONSTRAINT ck_projected_zone_price CHECK (price_amount >= 0),
    CONSTRAINT ck_projected_zone_currency CHECK (price_currency ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_projected_zone_capacity CHECK (capacity >= 1)
);

-- ---------------------------------------------------------------------------------------------
-- Tickets per zone. `reserved` is only ever changed by a conditional UPDATE, never by
-- read-modify-write; the CHECK is the last line of defence against overselling.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE zone_inventory (
    event_id uuid    NOT NULL,
    zone_id  uuid    NOT NULL,
    capacity integer NOT NULL,
    reserved integer NOT NULL DEFAULT 0,
    version  bigint  NOT NULL DEFAULT 0,
    PRIMARY KEY (event_id, zone_id),
    CONSTRAINT ck_zone_inventory_capacity CHECK (capacity >= 1),
    CONSTRAINT ck_zone_inventory_reserved CHECK (reserved >= 0 AND reserved <= capacity)
);

-- ---------------------------------------------------------------------------------------------
-- Bookings
-- ---------------------------------------------------------------------------------------------
CREATE TABLE booking (
    id                  uuid           PRIMARY KEY,
    user_id             uuid           NOT NULL,
    event_id            uuid           NOT NULL,
    status              varchar(16)    NOT NULL,
    total_amount        numeric(12, 2) NOT NULL,
    currency            varchar(3)     NOT NULL,
    created_at          timestamptz    NOT NULL,
    expires_at          timestamptz    NOT NULL,
    confirmed_at        timestamptz,
    expired_at          timestamptz,
    cancelled_at        timestamptz,
    cancel_reason       varchar(32),
    idempotency_key     uuid           NOT NULL,
    request_fingerprint varchar(64)    NOT NULL,
    version             bigint         NOT NULL DEFAULT 0,
    CONSTRAINT ck_booking_status CHECK (status IN ('PENDING', 'CONFIRMED', 'EXPIRED', 'CANCELLED')),
    CONSTRAINT ck_booking_cancel_reason CHECK (cancel_reason IS NULL OR cancel_reason IN ('USER_REQUEST', 'EVENT_CANCELLED')),
    CONSTRAINT ck_booking_total CHECK (total_amount >= 0),
    CONSTRAINT ck_booking_currency CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT ck_booking_confirmed_has_instant CHECK (status <> 'CONFIRMED' OR confirmed_at IS NOT NULL),
    CONSTRAINT ck_booking_expired_has_instant CHECK ((status = 'EXPIRED') = (expired_at IS NOT NULL)),
    CONSTRAINT ck_booking_cancelled_has_instant CHECK ((status = 'CANCELLED') = (cancelled_at IS NOT NULL)),
    CONSTRAINT ck_booking_cancelled_has_reason CHECK ((cancelled_at IS NOT NULL) = (cancel_reason IS NOT NULL)),
    -- One answer per (user, Idempotency-Key): the concurrent duplicate loses here, not in code.
    CONSTRAINT uq_booking_user_idempotency UNIQUE (user_id, idempotency_key)
);

-- "My bookings", newest first (GET /bookings, optionally filtered by status).
CREATE INDEX idx_booking_user_created ON booking (user_id, created_at DESC, id DESC);

-- The expiration job reads only PENDING bookings whose hold ended, oldest first: the partial index
-- stays as small as the set of live holds, however many finished bookings pile up.
CREATE INDEX idx_booking_expirable ON booking (expires_at, id) WHERE status = 'PENDING';

-- The cancellation cascade of an event walks its live bookings in batches.
CREATE INDEX idx_booking_active_by_event ON booking (event_id, created_at, id)
    WHERE status IN ('PENDING', 'CONFIRMED');

CREATE TABLE booking_item (
    booking_id          uuid           NOT NULL REFERENCES booking (id) ON DELETE CASCADE,
    zone_id             uuid           NOT NULL,
    position integer       NOT NULL,
    zone_name           text           NOT NULL,
    quantity            integer        NOT NULL,
    unit_price_amount   numeric(12, 2) NOT NULL,
    unit_price_currency varchar(3)     NOT NULL,
    PRIMARY KEY (booking_id, zone_id),
    CONSTRAINT ck_booking_item_quantity CHECK (quantity >= 1),
    CONSTRAINT ck_booking_item_price CHECK (unit_price_amount >= 0),
    CONSTRAINT ck_booking_item_currency CHECK (unit_price_currency ~ '^[A-Z]{3}$')
);

-- ---------------------------------------------------------------------------------------------
-- Payments: one row per charge attempt. A declined attempt stays as history; a new attempt is a
-- new row. attempts / next_attempt_at / last_error belong to the reconciler.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE payment (
    id              uuid           PRIMARY KEY,
    booking_id      uuid           NOT NULL REFERENCES booking (id),
    status          varchar(16)    NOT NULL,
    amount          numeric(12, 2) NOT NULL,
    currency        varchar(3)     NOT NULL,
    payment_token   varchar(80),
    refund_reason   varchar(40),
    created_at      timestamptz    NOT NULL,
    attempts        integer        NOT NULL DEFAULT 0,
    next_attempt_at timestamptz,
    last_error      text,
    version         bigint         NOT NULL DEFAULT 0,
    CONSTRAINT ck_payment_status CHECK (status IN ('INITIATED', 'DECLINED', 'CAPTURED', 'REFUND_PENDING', 'REFUNDED')),
    CONSTRAINT ck_payment_amount CHECK (amount >= 0),
    CONSTRAINT ck_payment_currency CHECK (currency ~ '^[A-Z]{3}$'),
    -- The opaque token exists only while a charge may still have to be repeated.
    CONSTRAINT ck_payment_token_only_while_initiated CHECK (payment_token IS NULL OR status = 'INITIATED'),
    CONSTRAINT ck_payment_refund_reason CHECK (
        (refund_reason IS NOT NULL) = (status IN ('REFUND_PENDING', 'REFUNDED'))
        AND (refund_reason IS NULL OR refund_reason IN
             ('BOOKING_EXPIRED_DURING_PAYMENT', 'BOOKING_CANCELLED', 'EVENT_CANCELLED')))
);

-- At most one live payment per booking: two concurrent pay requests cannot both record an attempt.
CREATE UNIQUE INDEX uq_payment_active_per_booking ON payment (booking_id)
    WHERE status IN ('INITIATED', 'CAPTURED', 'REFUND_PENDING');

-- Loading the payments of one or many bookings.
CREATE INDEX idx_payment_booking ON payment (booking_id);

-- The reconciler looks for payments nobody is finishing: refunds pending and charges left
-- initiated, whose next attempt is due. Settled payments are not in the index.
CREATE INDEX idx_payment_reconcile ON payment (status, next_attempt_at)
    WHERE status IN ('INITIATED', 'REFUND_PENDING');

-- ---------------------------------------------------------------------------------------------
-- Idempotent consumers: a message id is processed once.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE processed_message (
    message_id   uuid        PRIMARY KEY,
    processed_at timestamptz NOT NULL
);

-- ---------------------------------------------------------------------------------------------
-- Transactional outbox (same final shape as catalog-service). The relay arrives in a later
-- milestone; the table is part of the schema from the start so the aggregate and its events
-- share one transaction.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE outbox_event (
    id              uuid        PRIMARY KEY,
    aggregate_type  text        NOT NULL,
    aggregate_id    uuid        NOT NULL,
    event_type      text        NOT NULL,
    event_version   integer     NOT NULL,
    payload         jsonb       NOT NULL,
    correlation_id  uuid        NOT NULL,
    created_at      timestamptz NOT NULL,
    published_at    timestamptz,
    attempts        integer     NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL,
    last_error      text
);

-- The relay scans unpublished rows in creation order.
CREATE INDEX idx_outbox_event_pending ON outbox_event (created_at, id) WHERE published_at IS NULL;

-- Per-aggregate ordering: a row is sent only if no earlier unpublished row of its aggregate exists.
CREATE INDEX idx_outbox_event_unpublished_by_aggregate
    ON outbox_event (aggregate_id, created_at, id) WHERE published_at IS NULL;
